  "xhwanc": "কেন্দ্র দখল করুন, প্রথমে ঘোড়া ও হাতি বের করুন, তাড়াতাড়ি ক্যাসলিং করুন, আর প্রয়োজন ছাড়া এক ঘুঁটি দুবার চালবেন না।",
  "1ulggiy": "১০ম চালের আগে ক্যাসলিং করুন এবং বোড়ে দিয়ে রাজাকে ঢেকে রাখুন; শত্রুর রাজা মাঝখানে থাকলে কেন্দ্র খুলে আক্রমণ করুন।",
  "1t15fl6": "কৌশল না থাকলে: সবচেয়ে দুর্বল ঘুঁটি খুঁজে ভালো ঘরে আনুন, আর নৌকা দিয়ে খোলা ফাইল দখল করুন।",
  "1fs9wy0": "ঘুঁটিতে এগিয়ে থাকলে: বদলাবদলি করুন, রাজাকে এগিয়ে আনুন, মুক্ত বোড়ে এগোন। তাড়াহুড়ো নয়: প্রতিটি চাল যাচাই করুন যাতে অচলাবস্থা না হয়।",
  "7xpp3j": "1.e4-এর জবাবে 1...e5 খেলুন (ওপেন গেম)",
