  "14vtojm": "1.d4-এর বিরুদ্ধে কালো নিয়ে:",
  "1kzm3jo": "যে ওপেনিং আপনি এখন সবচেয়ে খারাপ খেলেন:",
  "1btgvys": "যে পর্যায়ে আপনি সবচেয়ে ভালো খেলেন তা হলো",
  "1pt5m6n": "এগুলোতে আপনার কদাচিৎ সমস্যা হয়:",
  "16dg98h": "প্রশ্নটি বুঝিনি এবং জ্ঞান লাইব্রেরিতে মিল পাওয়া কোনো নিবন্ধ পাইনি। নিচের একটি পরামর্শ বা ছোট কিওয়ার্ড চেষ্টা করুন (যেমন: পিন, মুক্ত বোড়ে, লুসেনা)।",
  "hwnfby": "সার্ভার ব্যস্ত, কয়েক মিনিট পরে চেষ্টা করুন।",
  "1b2hmqy": "সহকারীর সার্ভারে সংযোগ হয়নি।",
  "1d5b5ty": "সার্ভার ব্যস্ত, আবার চেষ্টা হচ্ছে…",
  "rq1kpk": "উত্তর বের করতে পারিনি, অন্যভাবে জিজ্ঞেস করে দেখুন।",
  "15d632n": "সহকারীর সার্ভারে ত্রুটি হয়েছে।",
  "gqs80q": "Stockfish 19 গেম বিশ্লেষণ করছে",
  "uemrrc": "কম্পিউটার বা অনলাইনে কয়েকটি গেম খেলুন: Stockfish 19 প্রতিটি চাল মূল্যায়ন করে, আর সহকারী দুর্বলতা খুঁজে আপনার জন্য পরিকল্পনা বানায়।",
  "1f3rsx8": "আপনার সাধারণ ওপেনিং ও প্রতিটিতে স্কোর দেখতে শুরুর অবস্থান থেকে কয়েকটি গেম খেলুন।",
  "11u3lth": "আপনার ইতিহাসে এখনও কোনো গেম নেই। কম্পিউটার বা অনলাইনে একটি গেম খেলুন, সহকারীর পর্যালোচনার জন্য এখানে দেখা যাবে।",
