  "1hki4wt": "আমার খেলার সবচেয়ে বড় দুর্বলতা কী এবং কীভাবে ঠিক করব?",
  "19ki7l6": "আজ প্রায় ৩০ মিনিট কী অনুশীলন করব?",
  "3eh4u9": "বোর্ডের অবস্থান আমার জন্য বিশ্লেষণ করুন",
